// Donna — the ONE coding state (RT-16, docs/plan-2026-09-01-runtime-refactor-slices.md
// §5 "Coding-state collapse"; audit F-14, the coding half).
//
// WHAT THIS COLLAPSES. A bank line's coding lifecycle used to live in THREE
// vocabularies with no machine between them:
//   - transaction_review_queue.review_state (migrations 004/008, nine labels:
//     suggested / accepted / asked_client / waiting / resolved / synced /
//     posted / closed / held), one queue row per line, regenerated by the
//     transaction-intel pass;
//   - payload.review_state on BOTH the queue row and the transaction (the
//     same nine labels, stamped by ~15 writers, each deciding on its own);
//   - payload.ai_suggestion_status on the transaction (suggested / applied /
//     alternative_applied / reviewer_applied / auto_applied) — the coder's
//     own receipt, read as a fourth state axis by the terminal checks.
// Every reader merged them with its own precedence (the snapshot read the
// queue column first, the coder's terminal check read the transaction
// payload, the Xero export merged the queue row over the transaction), so a
// line could be "accepted" on one surface and "suggested" on the next (the
// RT-13 appliance fixture's Leak B: a queue row minted at 'suggested' with
// no proposal behind it outranked a settled, owner-answered line).
//
// WHAT REPLACES THEM. `transactions.coding_state` (migration 138) — ONE
// persisted column with an explicit machine:
//
//   (none) ─┬─→ proposed ──┬─→ applied ──┬─→ posted ──┬─→ synced ──→ closed
//           │              ├─→ asked     │            │
//           │              └─→ held      └─→ closed   └─→ closed
//           └─→ applied | asked | held   (a rule / a firm click / an ask can
//                                          land before any proposal)
//
//   proposed  the coder (or a parse-time rule at yellow confidence) named an
//             account; nobody has decided. FIRM-SIDE LIMBO in the
//             convergence law (hanging) — the state the coding auto-post
//             sweep drives out.
//   applied   a decision: Donna auto-applied, a human accepted / recoded /
//             resolved the review case. Terminal 1 for the coding axis.
//   asked     an owner ask is out on the line (client audience only —
//             seat / agent asks never park a line here). Terminal 2 while
//             the ask is open; F8 makes an answered ask Donna's work again.
//   held      a reviewer hold. Firm-side, hanging, surfaced.
//   posted    a ledger journal exists for the line (postLedgerTransactionInDb).
//   synced    the journal is mirrored to the external ledger (Xero writeback).
//   closed    the period is closed over the line. No live writer yet; the
//             close path names it as the last rung.
//   NULL      nothing has been proposed, decided or asked for this line — a
//             freshly parsed line, an imported coded line. NOT "suggested":
//             the review-queue row the transaction-intel pass mints is a
//             CASE FILE (reason, priority, ask anchors), never a coding state.
//
// The transition table below is the whole law; `applyCodingTransition` is
// the ONE writer of the column and REFUSES (CODING_STATE_TRANSITION_INVALID,
// the writer's transaction rolls back) an undeclared move. posted / synced
// are ledger FACTS: reachable from every open state (a human posting an
// undecided line is the strongest possible apply — the journal is the
// receipt), never left except to each other or to closed (a reverse of a
// posted line is a ledger adjustment, reverseExecutor.js).
//
// WHAT STAYS, RENAMED IN MEANING. `payload.ai_suggestion_status` keeps ONLY
// its applied-family values (APPLIED_SUGGESTION_RECEIPTS) as the receipt of
// HOW a proposal was applied — Donna (auto_applied), the firm accepting the
// model's pick (applied), an alternative (alternative_applied), the
// reviewer's own account (reviewer_applied). It is no longer a state: the
// 'suggested' value is retired (migration 138 strips it) and every reader
// that meant "still proposed" reads `coding_state = 'proposed'`. Readers of
// `= 'auto_applied'` (the matcher's machine-explanation carve-out,
// reconciliationLlmCore.js) keep their receipt untouched.
//
// THE API CONTRACT IS UNCHANGED. Patches from the SPA / chat still carry the
// legacy labels (`review_state: 'accepted'`, `ai_suggestion_status:
// 'applied'`, `status: 'needs_client'`); `nextCodingStateForPatch` maps them
// onto the machine at the writer. DTOs still render `review_state` — as a
// PROJECTION of the column (`legacyReviewStateFor`), never a second copy in
// the data. `DECIDED_TRANSACTION_REVIEW_STATES` keeps its byte-identical
// meaning for the close path: DECIDED_CODING_STATES is its image under the
// mapping, pinned by codingState.test.js.
//
// Memory-plane fence (DMEM-R1): this is plane-S OPERATIONAL state. Nothing
// here is memory, and nothing here writes firm_facts / memory_* /
// client_rules / accounting_rules.

export const CODING_STATES = Object.freeze(['proposed', 'applied', 'asked', 'held', 'posted', 'synced', 'closed']);
export const CODING_STATE_SET = new Set(CODING_STATES);

// The FROM key for "never coded".
export const CODING_STATE_NONE_KEY = 'none';

// The transition table. Keys are FROM states (CODING_STATE_NONE_KEY for a
// NULL column); values are the states a writer may move to. Self-moves are
// declared where a writer legitimately re-stamps the same state (a fresh
// proposal on a proposed line, a re-ask, a re-post under force).
export const CODING_STATE_TRANSITIONS = Object.freeze({
  [CODING_STATE_NONE_KEY]: Object.freeze(['proposed', 'applied', 'asked', 'held', 'posted', 'synced']),
  proposed: Object.freeze(['proposed', 'applied', 'asked', 'held', 'posted', 'synced']),
  applied: Object.freeze(['proposed', 'applied', 'asked', 'held', 'posted', 'synced', 'closed']),
  asked: Object.freeze(['proposed', 'applied', 'asked', 'held', 'posted', 'synced']),
  held: Object.freeze(['proposed', 'applied', 'asked', 'held', 'posted', 'synced']),
  posted: Object.freeze(['posted', 'synced', 'closed']),
  synced: Object.freeze(['posted', 'synced', 'closed']),
  closed: Object.freeze(['closed'])
});

const norm = (v) => String(v ?? '').trim().toLowerCase();

export const isCodingState = (value) => CODING_STATE_SET.has(norm(value));

export const normalizeCodingState = (value) => (isCodingState(value) ? norm(value) : null);

const fromKey = (from) => (from == null || from === '' ? CODING_STATE_NONE_KEY : norm(from));

export const codingTransitionAllowed = (from, to) => {
  const target = normalizeCodingState(to);
  if (!target) return false;
  const allowed = CODING_STATE_TRANSITIONS[fromKey(from)];
  return Array.isArray(allowed) && allowed.includes(target);
};

// The FROM states from which `to` is reachable — for SQL-only writers that
// encode the guard in their WHERE (`coding_state is null` for the none key).
export const codingStatesAllowingTransitionTo = (to) => {
  const target = normalizeCodingState(to);
  if (!target) return [];
  return Object.entries(CODING_STATE_TRANSITIONS)
    .filter(([, allowed]) => allowed.includes(target))
    .map(([from]) => from);
};

export const codingTransitionGuardSql = (to, column = 'coding_state') => {
  const froms = codingStatesAllowingTransitionTo(to);
  const parts = [];
  if (froms.includes(CODING_STATE_NONE_KEY)) parts.push(`${column} is null`);
  const named = froms.filter((f) => f !== CODING_STATE_NONE_KEY);
  if (named.length) parts.push(`${column} in (${named.map((f) => `'${f}'`).join(', ')})`);
  return parts.length ? `(${parts.join(' or ')})` : 'false';
};

export class CodingStateTransitionError extends Error {
  constructor({ from = null, to = null, transactionId = null } = {}) {
    super(`Coding state transition refused: ${from ?? 'none'} → ${to ?? 'none'}${transactionId ? ` (transaction ${transactionId})` : ''}.`);
    this.name = 'CodingStateTransitionError';
    this.code = 'CODING_STATE_TRANSITION_INVALID';
    this.statusCode = 409;
    this.from = from ?? null;
    this.to = to ?? null;
    this.transactionId = transactionId ?? null;
  }
}

export const assertCodingTransition = (from, to, { transactionId = null } = {}) => {
  if (!codingTransitionAllowed(from, to)) {
    throw new CodingStateTransitionError({ from: from ?? null, to: normalizeCodingState(to) ?? to ?? null, transactionId });
  }
  return normalizeCodingState(to);
};

// ── The legacy vocabulary: input contract + DTO projection ──────────────────

// The nine review-state labels (migration 008's CHECK vocabulary, the SPA's
// src/lib/review-state.js contract). Kept as the INPUT vocabulary patches
// may carry and the label DTOs render; never persisted as state any more.
export const TRANSACTION_REVIEW_STATES = Object.freeze([
  'suggested', 'accepted', 'asked_client', 'waiting', 'resolved', 'synced', 'posted', 'closed', 'held'
]);
const TRANSACTION_REVIEW_STATE_SET = new Set(TRANSACTION_REVIEW_STATES);

const TRANSACTION_REVIEW_STATE_ALIASES = new Map([
  ['asked client', 'asked_client'],
  ['asked-client', 'asked_client'],
  ['asked_client', 'asked_client'],
  ['ask_client', 'asked_client'],
  ['client_asked', 'asked_client'],
  ['client_requested', 'asked_client'],
  ['needs_client', 'waiting'],
  ['waiting_client', 'waiting'],
  ['waiting_for_client', 'waiting'],
  ['closed', 'resolved'],
  ['dismissed', 'resolved'],
  ['done', 'resolved'],
  ['xero_synced', 'synced'],
  ['posted_to_ledger', 'posted'],
  ['ledger_posted', 'posted']
]);

export const normalizeTransactionReviewState = (value) => {
  const normalized = String(value || '').trim().toLowerCase().replace(/\s+/g, '_');
  const canonical = TRANSACTION_REVIEW_STATE_ALIASES.get(normalized) || normalized;
  return TRANSACTION_REVIEW_STATE_SET.has(canonical) ? canonical : null;
};

// The legacy-input derivation (was firmDb.js deriveTransactionReviewState;
// pinned by transactionReviewStates.test.js). It reads a PATCH and, for the
// pre-138 shapes, a payload — the legacy signals a caller may still send
// (a needs_client status, an open evidence_request, a sync marker, an
// applied receipt, a reviewer note). Its 'suggested' default is the reason
// nextCodingStateForPatch below treats "no signal" as "no change" rather
// than as a proposal.
export const deriveTransactionReviewState = ({ payload = {}, status = 'open', patch = {} } = {}) => {
  const explicit = normalizeTransactionReviewState(patch.review_state || patch.reviewState || payload.review_state || payload.reviewState);
  if (explicit) return explicit;
  if (
    payload.xero_sync_status === 'synced' ||
    payload.xero_synced_at ||
    payload.synced_at ||
    patch.xero_sync_status === 'synced' ||
    patch.xero_synced_at ||
    patch.synced_at
  ) {
    return 'synced';
  }
  const reviewerNote = String(patch.reviewer_note || patch.note || '');
  if (
    payload.status === 'needs_client' ||
    payload.transaction_status === 'needs_client' ||
    // W1 (INV-14): a drafted question is asked; only a delivered one is `waiting`
    // (the sent_at test below) — a draft resolves to asked_client.
    ['draft', 'open'].includes(String(payload.evidence_request?.status || '')) ||
    patch.status === 'needs_client' ||
    ['draft', 'open'].includes(String(patch.evidence_request?.status || '')) ||
    /client evidence request|ask client|asked client/i.test(reviewerNote)
  ) {
    return patch.evidence_request?.sent_at || payload.evidence_request?.sent_at || /client evidence request/i.test(reviewerNote) ? 'waiting' : 'asked_client';
  }
  if (APPLIED_SUGGESTION_RECEIPTS.includes(String(payload.ai_suggestion_status || patch.ai_suggestion_status || ''))) {
    return 'accepted';
  }
  if (/applied|accepted/i.test(reviewerNote)) return 'accepted';
  // Accept canonical (resolved/cancelled — PR 3 vocabulary) plus the
  // legacy values still tolerated as input by reviewItem.js.
  if (status === 'resolved' || status === 'cancelled' || status === 'closed' || status === 'dismissed') return 'resolved';
  return 'suggested';
};

// Legacy label → machine state. accepted and resolved are the SAME decision
// (a human's word); asked_client and waiting the same ask. The difference
// they used to carry (whether the review CASE closes) is the case's own
// `status` column, not a coding state.
export const CODING_STATE_FROM_REVIEW_STATE = Object.freeze({
  suggested: 'proposed',
  accepted: 'applied',
  resolved: 'applied',
  asked_client: 'asked',
  waiting: 'asked',
  held: 'held',
  posted: 'posted',
  synced: 'synced',
  closed: 'closed'
});

// A raw label maps FIRST (the alias table folds the legacy queue-status
// 'closed' into 'resolved', which would otherwise erase the machine's
// closed rung); only then the aliases ('needs_client', 'ledger_posted', …).
export const codingStateFromReviewState = (value) => {
  const raw = norm(value);
  if (Object.prototype.hasOwnProperty.call(CODING_STATE_FROM_REVIEW_STATE, raw)) return CODING_STATE_FROM_REVIEW_STATE[raw];
  const legacy = normalizeTransactionReviewState(value);
  return legacy ? CODING_STATE_FROM_REVIEW_STATE[legacy] : null;
};

// Machine state → the label the DTOs render (src/lib/review-state.js meta:
// accepted/resolved both read "Reviewed", asked_client/waiting both "Asked",
// so the projection loses nothing a surface showed).
export const LEGACY_REVIEW_STATE_FOR_CODING_STATE = Object.freeze({
  proposed: 'suggested',
  applied: 'accepted',
  asked: 'waiting',
  held: 'held',
  posted: 'posted',
  synced: 'synced',
  closed: 'closed'
});

export const legacyReviewStateFor = (state) => {
  const s = normalizeCodingState(state);
  return s ? LEGACY_REVIEW_STATE_FOR_CODING_STATE[s] : null;
};

// The application RECEIPT values `payload.ai_suggestion_status` keeps.
export const APPLIED_SUGGESTION_RECEIPTS = Object.freeze(['applied', 'alternative_applied', 'reviewer_applied', 'auto_applied']);
export const isAppliedSuggestionReceipt = (value) => APPLIED_SUGGESTION_RECEIPTS.includes(norm(value));

// DECIDED_TRANSACTION_REVIEW_STATES (firmDb.js: accepted / resolved / synced
// / posted / closed / held) under the mapping — the close path's "decided"
// set, byte-identical in meaning. Pinned against the legacy constant by
// codingState.test.js.
export const DECIDED_CODING_STATES = Object.freeze(['applied', 'held', 'posted', 'synced', 'closed']);
export const isDecidedCodingState = (state) => DECIDED_CODING_STATES.includes(normalizeCodingState(state));

// The coder's "never re-pool" set (was __isTerminalCodingState): a decided
// line is never re-suggested; a proposed / asked / never-coded line may be.
export const TERMINAL_CODING_STATES = DECIDED_CODING_STATES;
export const isTerminalCodingState = (state) => isDecidedCodingState(state);

// The states that SETTLE a line in the convergence law (auto_reconciled).
export const RECONCILED_CODING_STATES = Object.freeze(['applied', 'posted', 'synced', 'closed']);
// The state that puts a line ON THE OWNER (terminal 2) while its ask is open.
export const OWNER_CODING_STATE = 'asked';
// The firm-side limbo states (hanging).
export const HANGING_CODING_STATES = Object.freeze(['proposed', 'held']);

// Convergence reason key for the coding axis (reconcileConvergenceState.js).
export const codingStateReasonKey = (state) => `coding_state:${normalizeCodingState(state) || 'none'}`;

// Whether landing in `state` closes the review CASE (transaction_review_queue
// status → 'resolved'). Was shouldCloseReviewForState minus 'resolved': an
// explicit legacy 'resolved' input still closes the case through
// `reviewCaseClosesForLegacyState` — the case-close intent rides the INPUT
// label, the coding state rides the column.
export const codingStateClosesReviewCase = (state) => ['posted', 'synced', 'closed', 'held'].includes(normalizeCodingState(state));
export const reviewCaseClosesForLegacyState = (legacy) =>
  ['resolved', 'synced', 'posted', 'closed', 'held'].includes(normalizeTransactionReviewState(legacy));

// The next coding state a legacy-shaped PATCH asks for, given the line's
// current state. Explicit first (`coding_state` in the machine vocabulary,
// or `review_state` / `reviewState` in the legacy one), then the legacy
// SIGNALS deriveTransactionReviewState reads off a patch (a sync marker, a
// needs_client stamp / open evidence_request / "asked client" note, an
// applied receipt, an "applied/accepted" note, a closing case status).
// NO signal ⇒ the current state stands (a description edit never mints a
// proposal — the pre-138 writer stamped 'suggested' on every update, which
// is exactly how a decided line got flattened).
export const nextCodingStateForPatch = ({ currentState = null, patch = {}, itemStatus = null } = {}) => {
  const current = normalizeCodingState(currentState);
  const explicitMachine = normalizeCodingState(patch?.coding_state ?? patch?.codingState);
  if (explicitMachine) return explicitMachine;
  const explicitLegacy = codingStateFromReviewState(patch?.review_state ?? patch?.reviewState);
  if (explicitLegacy) return explicitLegacy;
  const derived = deriveTransactionReviewState({ payload: {}, status: itemStatus || 'open', patch: patch || {} });
  if (derived === 'suggested') return current;
  return CODING_STATE_FROM_REVIEW_STATE[derived] ?? current;
};

// ── The backfill law (migration 138 — the mapping table in its header) ──────
//
// One line, three legacy sources: the newest transaction-typed review-queue
// row (its column and its payload label, its case status and whether its
// payload carried a proposal), the transaction's own payload label and
// coder receipt, plus the ledger / mirror / needs_client markers the old
// derivation fell back to. The labels are mapped onto the machine and the
// HIGHEST-ranked one wins (closed > synced > posted > held > asked >
// applied > proposed): the pre-138 readers each merged the sources with a
// different precedence, and the one thing they all agreed on was that a
// more-advanced label anywhere meant the line had reached it. A 'suggested'
// label with NO proposal anywhere (the case-file row minted at the queue
// default) maps to NULL — a case file is not a coding state. With no label
// at all, the old fallbacks apply in the old order: a needs_client stamp is
// an ask, a closed case with nothing else is a decision, else NULL.
export const CODING_STATE_RANK = Object.freeze({ proposed: 1, applied: 2, asked: 3, held: 4, posted: 5, synced: 6, closed: 7 });

export const codingStateFromLegacy = ({
  queueReviewState = null,
  queuePayloadReviewState = null,
  queueStatus = null,
  queueHasProposal = false,
  payloadReviewState = null,
  aiSuggestionStatus = null,
  hasProposal = false,
  xeroSynced = false,
  ledgerPosted = false,
  needsClient = false
} = {}) => {
  const receipt = norm(aiSuggestionStatus);
  const proposalExists = Boolean(hasProposal || queueHasProposal || receipt === 'suggested');
  const candidates = [queueReviewState, queuePayloadReviewState, payloadReviewState]
    .map(codingStateFromReviewState)
    .filter(Boolean);
  if (APPLIED_SUGGESTION_RECEIPTS.includes(receipt)) candidates.push('applied');
  else if (receipt === 'suggested') candidates.push('proposed');
  if (xeroSynced) candidates.push('synced');
  if (ledgerPosted) candidates.push('posted');
  let best = null;
  for (const state of candidates) {
    if (state === 'proposed' && !proposalExists) continue;
    if (!best || CODING_STATE_RANK[state] > CODING_STATE_RANK[best]) best = state;
  }
  if (best) return best;
  if (needsClient) return 'asked';
  if (['resolved', 'cancelled', 'closed', 'dismissed'].includes(norm(queueStatus))) return 'applied';
  return null;
};

// A line that reaches a coding state is no longer waiting on the provider:
// the coder's provider-failure receipt (db/coding.js
// CODING_PROVIDER_FAILURE_PAYLOAD_KEY; named here, not imported, to keep this
// module free of the coder) is removed in the same write.
const CODING_PROVIDER_FAILURE_KEY = 'coding_provider_failure';

// ── The ONE writer of the column ────────────────────────────────────────────
//
// Locks the line, reads its current state, refuses an undeclared move (the
// error propagates — the calling writer's transaction rolls back, nothing
// half-written), writes the column + its timestamp on change. A self-move
// writes nothing (the proposal may have changed; the STATE did not). The
// transactions AFTER trigger (137 + 138's column list) marks the row for the
// convergence settle, so the persisted verdict follows in the same commit.
export const applyCodingTransition = async (client, { firmId, transactionId, to, clientId = null } = {}) => {
  if (!client || typeof client.query !== 'function') throw new Error('applyCodingTransition needs a database client.');
  if (!firmId || !transactionId) throw new Error('applyCodingTransition needs firmId and transactionId.');
  const target = normalizeCodingState(to);
  if (!target) throw new CodingStateTransitionError({ from: null, to: to ?? null, transactionId });
  const prior = await client.query(
    `select coding_state from transactions
      where firm_id = $1 and id = $2 and ($3::text is null or client_id = $3)
      for update`,
    [firmId, transactionId, clientId]
  );
  if (!prior.rows.length) return { found: false, from: null, to: target, changed: false };
  const from = prior.rows[0].coding_state ?? null;
  assertCodingTransition(from, target, { transactionId });
  if (from === target) return { found: true, from, to: target, changed: false };
  await client.query(
    `update transactions
        set coding_state = $3, coding_state_as_of = now(), updated_at = now(),
            payload = payload - '${CODING_PROVIDER_FAILURE_KEY}'
      where firm_id = $1 and id = $2`,
    [firmId, transactionId, target]
  );
  return { found: true, from, to: target, changed: true };
};

// The ask stamps' variant: an owner ask on a line already on a ledger rung
// (posted / synced / closed) must NOT fail the ask — the ask exists and puts
// the line on the owner through the ask itself; the coding question is not
// what is open there. This is the ONLY writer allowed to skip: it reads the
// same lock, applies the same table, and reports the skip instead of
// throwing. Everything else goes through applyCodingTransition.
export const applyCodingTransitionIfAllowed = async (client, { firmId, transactionId, to, clientId = null } = {}) => {
  if (!client || typeof client.query !== 'function') throw new Error('applyCodingTransitionIfAllowed needs a database client.');
  if (!firmId || !transactionId) throw new Error('applyCodingTransitionIfAllowed needs firmId and transactionId.');
  const target = normalizeCodingState(to);
  if (!target) throw new CodingStateTransitionError({ from: null, to: to ?? null, transactionId });
  const prior = await client.query(
    `select coding_state from transactions
      where firm_id = $1 and id = $2 and ($3::text is null or client_id = $3)
      for update`,
    [firmId, transactionId, clientId]
  );
  if (!prior.rows.length) return { found: false, from: null, to: target, changed: false, skipped: false };
  const from = prior.rows[0].coding_state ?? null;
  if (!codingTransitionAllowed(from, target)) return { found: true, from, to: target, changed: false, skipped: true };
  if (from === target) return { found: true, from, to: target, changed: false, skipped: false };
  await client.query(
    `update transactions
        set coding_state = $3, coding_state_as_of = now(), updated_at = now(),
            payload = payload - '${CODING_PROVIDER_FAILURE_KEY}'
      where firm_id = $1 and id = $2`,
    [firmId, transactionId, target]
  );
  return { found: true, from, to: target, changed: true, skipped: false };
};
